
import { Goal } from './Goal';

export { } // For Type definition purposes

/**
 * This class allows registration of several different goal classes which can be achieved
 * in parallel.
 * @internal
 * @private
 * @class GoalParallelism
 * @memberof jibo.action.goal
 */
export class GoalParallelism {

    /**
     * A map representation of all goal constructors that can be acted on in parallel
     * @private
     * @memberOf GoalParallelism
     */
    private allowedConcurrentGoals = new Map<Function, Set<Function>>();

    /**
     * Determines whether the two goals can be achieved in parallel
     * @param {Goal} goalA
     * @param {Goal} goalB
     * @returns {boolean}
     * @memberOf GoalParallelism
     */
    canBeAchievedInParallel(goalA: Goal, goalB: Goal): boolean {
        const set = this.allowedConcurrentGoals.get(goalA.constructor);
        if (!set) {
            return false;
        }
        return set.has(goalB.constructor);
    }

    /**
     * Registers two goal constructors that can be acted on in parallel
     * @param {Function} goalConstructorA
     * @param {Function} goalConstructorB
     * @memberOf GoalParallelism
     */
    public registerParallelGoalConstructors(goalConstructorA: Function, goalConstructorB: Function): void {
        this._addEntry(goalConstructorA, goalConstructorB);
        this._addEntry(goalConstructorB, goalConstructorA);
    }

    private _addEntry(first: Function, second: Function) {
        let set = this.allowedConcurrentGoals.get(first);
        if (!set) {
            set = new Set<Function>();
            this.allowedConcurrentGoals.set(first, set);
        }
        set.add(second);
    }
}
