import {AnimationAction} from './AnimationAction';
import {ActionRuntime} from '../../common/ActionRuntime';
import {DriveName} from '../../common/Types';
import {State} from '../../common/State';
import {SkillNames} from '../../common/Utils';
import {TimeUtils} from 'jibo-cai-utils';


export { }

/**
 * The class of "small" idle animations.
 *
 * @export
 * @class jibo.action.action.IdleAnimationSmall
 * @internal
 * @private
 * @extends {AnimationAction}
 */
export class IdleAnimationSmall extends AnimationAction {
    constructor (public parent: ActionRuntime) {
        super(parent, {
                category: 'idle',
                includeMeta: ['bored', 'playful'],
                randomOrientation: true
            },
            new Map<DriveName, number>([<[DriveName, number]>[DriveName.PLAYFUL, -1.0]]));
    }

    /**
     * Determines if this action is eligible in a given state
     * Should be overridden by subclasses
     * @param {object} state
     * @return {boolean}
     */
    isEligible(state: State): boolean {
        return (state.skillName===SkillNames.IDLE);  // is the Idle requirement redundant?
    }
}


/**
 * The class of "big" idle animations--those used after Jibo has been in Idle for a longer
 * period of time (currently 3 hours).
 * @export
 * @class jibo.action.action.IdleAnimationBig
 * @extends {AnimationAction}
 * @internal
 * @private
 */
export class IdleAnimationBig extends AnimationAction {
    constructor (public parent: ActionRuntime) {
        super(parent, {
                category: 'idle',
                includeMeta: ['bored', 'playful', 'big'],
                randomOrientation: true
            },
            new Map<DriveName, number>([<[DriveName, number]>[DriveName.PLAYFUL, -1.0]]));
    }

    /**
     * Determines if this action is eligible in a given state
     * Should be overridden by subclasses
     * @param {object} state
     * @return {boolean}
     */
    isEligible(state: State): boolean {
        return (state.skillName===SkillNames.IDLE) &&
            (Date.now() - state.skillStartTime.valueOf()) > TimeUtils.hoursToMs(3);  // is the Idle requirement redundant?
    }
}
