import {ActionRuntime} from './ActionRuntime';
import {DateProvider} from './DateProvider';
import {DriveName} from './Types';
import {FindPersonGoal} from '../goal/goals/FindPersonGoal';
import {ProactiveGreetingGoalProvider} from '../goal/goalproviders/ProactiveGreetingGoalProvider';

let tunable = null;
try {
    tunable = require('jibo-tunable');
} catch(e) {
    // No tunable library found, disabling debug
}

class FakeDateProvider implements DateProvider {
    constructor(private hour: number) { }

    getDate(): Date {
        const d = new Date();
        d.setHours(this.hour);
        return d;
    }
}

const WIN = 'Action System';

export class TunableDebug {

    static setup(ar: ActionRuntime) {
        if (tunable) {
            const T = tunable.Tunable;

            T.getButtonField(`Log status report`, WIN).events.change.on(() => {
                const state = ar.createState();
                ar.log.info(`Action System status:`);
                ar.log.info(`State: \n${JSON.stringify(state, null, 4)}`);
                ar.log.info(`Active goals/actions (${ar.activeGoals.length})`);
                ar.activeGoals.forEach(g => {
                    ar.log.info(` - goal: '${g.goal.name}', action: '${g.action.name}'`);
                });
            });

            T.getButtonField(`Force pro-active greeting`, WIN).events.change.on(() => {
                ar.goalProviders.forEach(gp => {
                    if (gp instanceof ProactiveGreetingGoalProvider) {
                        gp.handleVisibleFaceInternal();
                    }
                });
            });
            
            // Here we create an option to fake the time
            const originalDateProvider = ar.dateProvider;
            T.getDropdownField('Fake time', ['disabled', '7am', '2pm', '11pm'], 0, WIN).events.change.on(data => {
                if (data === 'disabled') {
                    ar.dateProvider = originalDateProvider;
                } else if (data === '7am') {
                    ar.dateProvider = new FakeDateProvider(7);
                } else if (data === '2pm') {
                    ar.dateProvider = new FakeDateProvider(14);
                } else if (data === '11pm') {
                    ar.dateProvider = new FakeDateProvider(23);
                }
                ar.circadianGoalProvider.update();
            });

            T.getButtonField(`Clear current goal / action`, WIN).events.change.on(() => {
                if (!ar.activeGoals.length) {
                    ar.log.warn(`No current goal/action to clear`);
                } else {
                    const name = ar.activeGoals.map(a => a.action.name).join(', ');
                    ar.log.warn(`Canceling current action: ${name}`);
                    ar.activeGoals.forEach(a => a.action.cancel());
                }
            });

            T.getButtonField(`Create search goal`, WIN).events.change.on(() => {
                ar.goals.addGoal(new FindPersonGoal(ar));
            });

            const driveDropdown = T.getDropdownField('Motivational drive', Object.keys(DriveName), 0, WIN);
            T.getButtonField(`Saturate drive`, WIN).events.change.on(() => {
                const drive = ar.motivations.drives.get(driveDropdown.current);
                (drive as any)._value = drive.threshold;
            });
        }
    }
}
