/**
 * Enum of the finished status of a goal
 * @typedef jibo.action.types#GoalFinishedStatus
 * @property {String} NOT_FINISHED
 * @property {String} SUCCEEDED
 * @property {String} FAILED
 * @property {String} CANCELED
 * @property {String} CULLED
 */
export type GoalFinishedStatus = 'NOT_FINISHED'|'SUCCEEDED'|'FAILED'|'CANCELED'|'CULLED';
export namespace GoalFinishedStatus {
    export const NOT_FINISHED: GoalFinishedStatus = 'NOT_FINISHED';
    export const SUCCEEDED: GoalFinishedStatus = 'SUCCEEDED';
    export const FAILED: GoalFinishedStatus = 'FAILED';
    export const CANCELED: GoalFinishedStatus = 'CANCELED';
    export const CULLED: GoalFinishedStatus = 'CULLED';
}

