import {ActionRuntime} from '../../common/ActionRuntime';
import {SkillNames} from '../../common/Utils';
import {TimeOfDay} from '../../common/Types';
import {GoalProvider} from '../GoalProvider';
import {GoalPriority} from '../GoalPriority';
import {SSWGoal} from '../goals/SSWGoal';


export {} // For Type definition purposes

/**
 * @internal
 * @private
 */
export class CircadianGoalProvider extends GoalProvider {

    private lastToD: TimeOfDay;
    
    constructor(parent: ActionRuntime) {
        super(parent, 'Circadian rhythm goal provider');
    }

    init() {
        // noop
    }

    dispose() { 
        // noop        
    }

    public update() {
        const now = this.parent.dateProvider.getDate();
        if (this.parent.currentSkillName === SkillNames.IDLE) {
            let intent: string;
            // Check to see if the Time of day has changed since last
            const tod = TimeOfDay.getTimeOfDay(now.getHours());
            if (tod !== this.lastToD) {
                if (tod === TimeOfDay.DAY) {
                    intent = 'dayTime';
                }
                else if (tod === TimeOfDay.NIGHT) {
                    intent = 'nightTime';
                }
                this.lastToD = tod;
            }

            if (intent) {
                const goal = new SSWGoal(this.parent, {
                    skillName: SkillNames.IDLE,
                    skillOptions: {
                        intent: intent,
                    },
                    criteria: {
                        currentSkill: SkillNames.IDLE
                    }
                }, `Idle Time of Day: '${intent}'`);
                goal.options.priority = GoalPriority.Circadian;

                this.provideGoal(goal);
            }
        }
    }
}
