import {Drive} from '../Drive';
import {TimeOfDay, DriveName} from '../../common/Types';
import {ActionRuntime} from '../../common/ActionRuntime';


export {}

/**
 * @internal
 * @private
 */
export class PlayfulDrive extends Drive {

    private _daytimeRatePerMin: number;
    constructor(private parent: ActionRuntime) {
        super(DriveName.PLAYFUL, 1/15);
        this._daytimeRatePerMin = this.ratePerMin;
    }

    public update() {
        // check time of day. if it's not daytime, set ratePerMin to 0. If it is daytime, set to _daytimeRatePerMin
        const now = this.parent.dateProvider.getDate();
        const tod = TimeOfDay.getTimeOfDay(now.getHours());
        if (tod === TimeOfDay.DAY) {
            this.ratePerMin = this._daytimeRatePerMin;
        } else {
            this.ratePerMin = 0;
        }
        super.update();
    }

}